with enriched as (select *, sum(duration_sec) over w_hist as running_sum_duration_sec, max(duration_sec) over w_hist as running_max_duration_sec, avg(duration_sec) over w_hist as running_avg_duration_sec from web_events window w_hist as (partition by session_id order by duration_sec, id rows between unbounded preceding and current row)) select s.id, s.session_id, s.event_type, s.duration_sec, s.running_sum_duration_sec, s.running_avg_duration_sec, (select min(x.duration_sec) from web_events x where x.session_id = s.session_id) as min_web_event_duration_sec from enriched s;
